Here is binary search implemented in C:

```c
#include <stdio.h>

int binary_search(int arr[], int size, int target) {
    int low = 0, high = size - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] == target) return mid;
        if (arr[mid] < target) low = mid + 1;
        else high = mid - 1;
    }
    return -1;
}

int main() {
    int data[] = { 3, 7, 12, 19, 25, 33, 42 };
    int idx = binary_search(data, 7, 25);
    printf("Found target 25 at index: %d\n", idx);
    return 0;
}
```

